/* Dicke state |D^4_2>, Bärtschi & Eidenbenz (2019): start |0011>, then SCS_{4,2}, SCS_{3,2}, SCS_{2,1}.
 * Plain C gates: a CNOT is `t ^= c`, a CRy is `if (c) cq_theta(&t, a)`, a CCRy is `s = 2*a + b; if (s == 3) cq_theta(&t, a)`.
 * The result is the four measured bits, q1 in bit 0. */
#include <math.h>
int dicke4(void) {
    bool q1 = 0, q2 = 0, q3 = 1, q4 = 1;
    int s;
    /* SCS_{4,2} */
    q4 ^= q3;
    if (q4) cq_theta(&q3, 2.0 * acos(sqrt(1.0 / 4)));
    q4 ^= q3;
    q4 ^= q2;
    s = 2 * q4 + q3;
    if (s == 3) cq_theta(&q2, 2.0 * acos(sqrt(2.0 / 4)));
    q4 ^= q2;
    /* SCS_{3,2} */
    q3 ^= q2;
    if (q3) cq_theta(&q2, 2.0 * acos(sqrt(1.0 / 3)));
    q3 ^= q2;
    q3 ^= q1;
    s = 2 * q3 + q2;
    if (s == 3) cq_theta(&q1, 2.0 * acos(sqrt(2.0 / 3)));
    q3 ^= q1;
    /* SCS_{2,1} */
    q2 ^= q1;
    if (q2) cq_theta(&q1, 2.0 * acos(sqrt(1.0 / 2)));
    q2 ^= q1;
    return cq_measure(q1) | cq_measure(q2) << 1 | cq_measure(q3) << 2 | cq_measure(q4) << 3;
}

/* Dicke state |D^n_k> for runtime n, k, Bärtschi & Eidenbenz (2019): start |0^{n-k} 1^k>, then SCS_{m, min(k, m-1)}
 * for m = n down to 2. Qubits q[0..n-1] in a runtime-sized register; SCS_m acts on q[0..m-1] with q[m-1] as its last
 * qubit. Plain C gates as in 113 (the fixed-size N = 4, K = 2 instance). The result is the measured bits, q[0] in
 * bit 0 (n <= 31). */
#include <math.h>
int dicke_n(int n, int k) {
    bool q[n];
    for (int i = 0; i < n; i++) q[i] = (i >= n - k);
    for (int m = n; m >= 2; m--) {
        int kk = k < m - 1 ? k : m - 1;
        /* 2-qubit block on (q[m-2], q[m-1]) */
        q[m - 1] ^= q[m - 2];
        if (q[m - 1]) cq_theta(&q[m - 2], 2.0 * acos(sqrt(1.0 / m)));
        q[m - 1] ^= q[m - 2];
        /* 3-qubit blocks l = 2..kk on (q[m-1-l], q[m-l], q[m-1]) */
        for (int l = 2; l <= kk; l++) {
            q[m - 1] ^= q[m - 1 - l];
            int s = 2 * q[m - 1] + q[m - l];
            if (s == 3) cq_theta(&q[m - 1 - l], 2.0 * acos(sqrt((double)l / m)));
            q[m - 1] ^= q[m - 1 - l];
        }
    }
    int r = 0;
    for (int i = 0; i < n; i++) r |= cq_measure(q[i]) << i;
    return r;
}

/* QAOA for MaxCut (Farhi, Goldstone, Gutmann 2014) on a graph given at run time: n vertices, ne edges (eu[e], ev[e]),
 * p layers with angles gamma[l], beta[l]:
 *   |psi> = prod_l U_B(beta_l) U_C(gamma_l) |+>^n,  U_C = exp(-i gamma C),  C = sum_e [x_eu[e] != x_ev[e]],
 *   U_B = prod_i Rx(2 beta) = prod_i Rz(-pi/2) Ry(2 beta) Rz(pi/2)  (up to a global phase).
 * Sizes and problem data are inputs, never compile-time constants. Returns the measured bits x0 | x1<<1 | ... */
#include <math.h>
int qaoa_ring(int n, int ne, const int *eu, const int *ev, int p, const double *gamma, const double *beta) {
    bool x[n];
    for (int i = 0; i < n; i++) {
        x[i] = 0;
        cq_theta(&x[i], M_PI / 2);                                 /* |+>^n */
    }
    for (int l = 0; l < p; l++) {
        for (int e = 0; e < ne; e++)                               /* cost layer */
            if (x[eu[e]] != x[ev[e]]) cq_phi(-gamma[l]);
        for (int i = 0; i < n; i++) {                              /* mixer layer: Rx(2 beta) */
            if (x[i]) cq_phi(M_PI / 2);
            cq_theta(&x[i], 2 * beta[l]);
            if (x[i]) cq_phi(-M_PI / 2);
        }
    }
    int m = 0;
    for (int i = 0; i < n; i++) m |= cq_measure(x[i]) << i;
    return m;
}

/* Shor order finding for N = 15, a = 7 (r = 4): the quantum part of the textbook program.
 *   counting register x[0..T-1] (x[0] = LSB), work register y
 *   1. H on every counting qubit            H|0> = Ry(pi/2)|0>
 *   2. y = a^x mod N by repeated squaring   controlled y *= a^(2^j) mod N  (the loop of example 62)
 *   3. inverse QFT on the counting register (the loops of example 60; H = Ry(pi/2)·Z on a superposed qubit)
 *   4. measure m and y; the continued-fraction post-processing is classical and left out.
 * Expected: m uniform on {0, 2, 4, 6}, y in {1, 7, 4, 13} correlated with x (period r = 4). */
#include <stdbool.h>
#include <math.h>
#define N 15u
#define A 7u
#define T 3
unsigned shor15(void) {
    bool x[T] = {0};
    for (int j = 0; j < T; j++)
        cq_theta(&x[j], M_PI / 2);
    unsigned y = 1, ap = A % N;
    for (int j = 0; j < T; j++) {
        if (x[j]) y = (y * ap) % N;
        ap = (ap * ap) % N;
    }
    for (int j = 0; j < T; j++) {                  /* logical qubit j is x[T-1-j] (final swaps folded into the labels) */
        for (int k = 0; k < j; k++)
            if (x[T - 1 - k] && x[T - 1 - j]) cq_phi(-M_PI / (double)(1u << (j - k)));
        if (x[T - 1 - j]) cq_phi(M_PI);
        cq_theta(&x[T - 1 - j], M_PI / 2);
    }
    unsigned m = 0;
    for (int j = 0; j < T; j++)
        m |= (unsigned)cq_measure(x[T - 1 - j]) << j;
    unsigned yv = cq_measure(y);
    return m | (yv << 8);
}

/* Quantum counting = QPE on the Grover iterate (Brassard, Hoyer, Tapp; Nielsen & Chuang 6.3), textbook form, general size.
 *   A = Ry(pi/2)^nq (A|0> = |s>), O = I - 2 sum_{marked} |x><x|, R = 2|0><0| - I, G = A R A^dag O.
 *   H^t on c; controlled G^(2^j) on c[j]; QFT^-1 on c; measure m; M~ = 2^nq sin^2(pi m / 2^t).
 * `if (c[j]) grover(...)` is a CONTROLLED COMPOSITE U: a helper with loops, rotations and phases under one control.
 * Sizes and problem data are inputs: nq search qubits, t counting qubits, the marked list `marked[0..nmark)`.
 * Driver instances: nq = 3, t = 4, marked {3, 5}: P(round(M~) = 2) = 0.69; nq = 3, t = 3, marked {1}. */
#include <stdbool.h>
#include <math.h>

static int value(const bool x[], int nq) {
    int v = 0;
    for (int i = 0; i < nq; i++) v |= x[i] << i;
    return v;
}
static bool is_marked(int v, const int *marked, int nmark) {
    for (int k = 0; k < nmark; k++)
        if (v == marked[k]) return true;
    return false;
}
__attribute__((noinline)) static void grover(bool x[], int nq, const int *marked, int nmark) {  /* G = A R A^dag O */
    if (is_marked(value(x, nq), marked, nmark)) cq_phi(M_PI);    /* O */
    for (int i = 0; i < nq; i++) cq_theta(&x[i], -M_PI / 2);    /* A^dag */
    if (value(x, nq) != 0) cq_phi(M_PI);                         /* R */
    for (int i = 0; i < nq; i++) cq_theta(&x[i], M_PI / 2);     /* A */
}
int qpe_counting(int nq, int t, const int *marked, int nmark) {
    bool c[t], x[nq];
    for (int j = 0; j < t; j++) c[j] = false;
    for (int i = 0; i < nq; i++) x[i] = false;
    for (int j = 0; j < t; j++) cq_theta(&c[j], M_PI / 2);      /* H^t */
    for (int i = 0; i < nq; i++) cq_theta(&x[i], M_PI / 2);     /* A */
    for (int j = 0; j < t; j++)                                 /* controlled G^(2^j) */
        for (int k = 0; k < (1 << j); k++)
            if (c[j]) grover(x, nq, marked, nmark);
    for (int j = t - 1; j >= 0; j--) {                          /* QFT^-1 without the final swaps */
        for (int k = t - 1; k > j; k--)
            if (c[k] && c[j]) cq_phi(-M_PI / (1 << (k - j)));
        if (c[j]) cq_phi(M_PI);
        cq_theta(&c[j], M_PI / 2);
    }
    int m = 0;
    for (int j = 0; j < t; j++) m |= (int)cq_measure(c[j]) << (t - 1 - j);
    return m;
}

/* QFT^-1 on four scalar qubits (no swaps), H = Ry(pi/2) Z, CPhase as `if (a && b) cq_phi(t)`. At -O1 the
 * short-circuit conditions are De-Morgan'd: negations hoisted as values, later conditions rewritten as or-selects. */
#include <math.h>
int qft4_demorgan(double th) {
    bool c0 = 0, c1 = 0, c2 = 0, c3 = 0;
    cq_theta(&c0, th); cq_theta(&c1, th); cq_theta(&c2, th); cq_theta(&c3, th);
    if (c3) cq_phi(M_PI); cq_theta(&c3, M_PI / 2);
    if (c3 && c2) cq_phi(-M_PI / 2);
    if (c2) cq_phi(M_PI); cq_theta(&c2, M_PI / 2);
    if (c3 && c1) cq_phi(-M_PI / 4);
    if (c2 && c1) cq_phi(-M_PI / 2);
    if (c1) cq_phi(M_PI); cq_theta(&c1, M_PI / 2);
    if (c3 && c0) cq_phi(-M_PI / 8);
    if (c2 && c0) cq_phi(-M_PI / 4);
    if (c1 && c0) cq_phi(-M_PI / 2);
    if (c0) cq_phi(M_PI); cq_theta(&c0, M_PI / 2);
    return cq_measure(c0) | cq_measure(c1) << 1 | cq_measure(c2) << 2 | cq_measure(c3) << 3;
}

