#include <stdbool.h>
static const int GRID[4][4] = {{3, 1, 4, 1}, {5, 9, 2, 6}, {5, 3, 5, 8}, {9, 7, 9, 3}};
int table_2d(unsigned r0, unsigned c0, double tr, double tc) {
    unsigned r = r0, c = c0;
    cq_theta(&r, tr);
    cq_theta(&c, tc);
    return cq_measure(GRID[r & 3][c & 3]);            /* quantum row AND quantum column */
}
int register_grid(const double *theta, int rows, double c) {
    bool q[2][2] = {{0, 0}, {0, 0}};
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < 2; j++)
            cq_theta(&q[i][j], theta[2 * i + j]);
    for (int i = 0; i < rows; i++)
        if (q[i][0])                                  /* controlled Ry inside a row */
            cq_theta(&q[i][1], c);
    if (q[0][1])                                      /* controlled Ry across rows */
        cq_theta(&q[rows - 1][1], c);
    return cq_measure(q[0][1]) + cq_measure(q[rows - 1][1]);
}

int quantum_strlen(const double *th, int cap) {          /* cap <= 4: the buffer size */
    char s[4] = {0, 0, 0, 0};
    for (int i = 0; i < cap; i++) {
        s[i] = 'a';
        cq_theta(&s[i], th[i]);                            /* every char is quantum */
    }
    int n = 0;
    while (n < cap && s[n] != 0)                           /* exit on a quantum NUL, bounded by the buffer */
        n++;
    return cq_measure(n);
}
int quantum_strcmp(const double *ta, const double *tb, int cap) {
    char a[4] = {0, 0, 0, 0}, b[4] = {0, 0, 0, 0};
    for (int i = 0; i < cap; i++) {
        a[i] = b[i] = 'a';
        cq_theta(&a[i], ta[i]);
        cq_theta(&b[i], tb[i]);
    }
    int i = 0;
    while (i < cap && a[i] != 0 && a[i] == b[i])            /* two quantum exit conditions */
        i++;
    return cq_measure(i < cap ? a[i] - b[i] : 0);          /* the chars at the quantum exit index */
}

struct fields { unsigned a : 3, b : 5, c : 24; };        /* one 32-bit storage unit: a = bits 0-2, b = 3-7, c = 8-31 */
int quantum_bitfield(unsigned w0, double th, unsigned v, unsigned k, double ph) {
    unsigned w = w0;
    cq_theta(&w, th);                                    /* the whole storage unit is quantum */
    struct fields f;
    __builtin_memcpy(&f, &w, sizeof f);                  /* view the word as bit-fields */
    f.b = f.a + v;                                       /* read one field, write another: read-modify-write of the word */
    if (f.b > k)                                         /* quantum condition reading the field just written */
        cq_phi(ph);
    __builtin_memcpy(&w, &f, sizeof f);
    return cq_measure(w);                                /* the updated word is measured */
}
__attribute__((noinline)) static void bump_c(struct fields *p, unsigned d) {
    p->c += d;                                           /* RMW of the storage unit through a pointer, in a callee */
}
int bitfield_through_pointer(unsigned w0, double th, unsigned d, double ph) {
    struct fields f;
    unsigned w = w0;
    cq_theta(&w, th);
    __builtin_memcpy(&f, &w, sizeof f);
    bump_c(&f, d);                                       /* the struct stays in memory: a slot passed to a lifted call */
    if (f.a == 5)                                        /* quantum condition on a field the callee did not touch */
        cq_phi(ph);
    return cq_measure(f.c);
}

enum mode { RED, GREEN, BLUE, ALPHA };
int enum_switch_fallthrough(enum mode m0, double th, int y0, double p) {
    enum mode m = m0;
    cq_theta(&m, th);                       /* enum mode * is compatible with unsigned int *: a quantum enum */
