    return cq_measure(r) + cq_measure(f) + cq_measure(x);   /* ... and is read as data */
}
int compare_shared_by_region_and_angle(int x0, double th, int k, int r0, double p, double a, double b) {
    int x = x0;
    cq_theta(&x, th);
    if (x == k)
