__attribute__((noinline)) static void h(int f, double p) { if (f) cq_phi(p); }
int callee_phase_under_control(int x0, double tx, int k, double p, int f) {
    int x = x0;
    cq_theta(&x, tx);
    if (x > k) g(p);
    if (x > k) h(f, p);
    cq_phi(p);
    cq_theta(&x, -tx);
    return cq_measure(x);
}

