/* Rule 13 + rule 8: a switch inside a case arm of another switch, both scrutinees quantum. Inner case flags are
 * conjoined with the outer edge flag. The phase arm inside the inner switch kicks back on the conjunction. */
int nested_switch(int x0, double tx, int y0, double ty, int c, double p) {
    int x = x0, y = y0, r = c;
    cq_theta(&x, tx);
    cq_theta(&y, ty);
    switch (x & 3) {
        case 0: r += 1; break;
        case 1:
            switch (y & 3) {
                case 0: r += 2; break;
                case 2: cq_phi(p); break;
                default: r += y; break;
            }
            break;
        default: r += x; break;
    }
    return cq_measure(r);
}

/* Rule 14: `continue` on a quantum condition inside a classically bounded loop (the trip is skipped under a flag),
 * and `continue` inside a K-loop (quantum exit), where the skip flag joins the trip predicate chain. */
int continue_classical_bound(int x0, double tx, int n, int k, int c) {
    int x = x0, acc = 0;
    cq_theta(&x, tx);
    for (int i = 0; i < n; i++) {
        if (x == i + k) continue;
        acc = acc * c + i;
    }
    return cq_measure(acc) + cq_measure(x);
}
int continue_kloop(unsigned x0, double tx, unsigned k, unsigned c) {
    unsigned x = x0, s = 0;
    cq_theta(&x, tx);
    while (x > k) {           /* [K] */
        x -= 1;
        if (x & 1) continue;
        s += c;
    }
