/* Rule 9: value arms nested three deep on three quantum conditions; each level merges by select under its own flag,
 * flags conjoined per level. */
int value_arm_depth3(int x0, double tx, int y0, double ty, int z0, double tz, int a, int b, int c, int d) {
    int x = x0, y = y0, z = z0, r = a;
    cq_theta(&x, tx); cq_theta(&y, ty); cq_theta(&z, tz);
    if (x > a) {
        if (y > b) {
            if (z > c) r = x + y + z;
            else       r = x * y;
        } else {
            r = y - d;
        }
    } else {
        r = z + d;
    }
    return cq_measure(r);
}

/* Rule 26: a struct with a quantum field passed BY VALUE into a noinline callee and returned by value; both fields
 * quantum in the second entry. clang coerces { int, int } to i64 at the ABI: the clone takes the field handles. */
struct p2 { int a, b; };
__attribute__((noinline)) static struct p2 shift(struct p2 p, int c) { struct p2 r = { p.a + c, p.b * c }; return r; }
int struct_byvalue_one(int a0, double ta, int b, int c) {
    struct p2 p = { a0, b };
    cq_theta(&p.a, ta);
    struct p2 r = shift(p, c);
    return cq_measure(r.a + r.b);
}
int struct_byvalue_both(int a0, double ta, int b0, double tb, int c) {
    struct p2 p = { a0, b0 };
    cq_theta(&p.a, ta);
    cq_theta(&p.b, tb);
    struct p2 r = shift(p, c);
    return cq_measure(r.a) + cq_measure(r.b);
}

double fcmp_olt(double x0, double th, double k, double phi) {
    double x = x0; cq_theta(&x, th);
    if (x < k) cq_phi(phi);
    return cq_measure(x); }
double fcmp_unordered(double x0, double th, double k, double phi) {
    double x = x0; cq_theta(&x, th);
    if (!(x >= k)) cq_phi(phi);
    return cq_measure(x); }
double fcmp_qq(double x0, double y0, double tx, double ty, double phi) {
    double x = x0, y = y0; cq_theta(&x, tx); cq_theta(&y, ty);
    if (x == y) cq_phi(phi);
    return cq_measure(x); }

