    cq_theta(&j, tj);
    int x = x0;
    cq_theta(&x, tx);
    int a[4] = {1, 2, 3, 4};                  /* a bus-resident alloca; the initializer is a 16-byte copy */
    a[k & 3] = x;                             /* a kept store at an address rail */
    int r = a[j & 3];                         /* a load at another address rail */
    return cq_measure(r);
}

